using Ta3lom.Store.Domain.Events;
namespace Ta3lom.Store.Domain.Entities.Media;

/// Table `media_asset`: an uploaded file. Storage keys are generated by the server; images need Arabic alt text.
public sealed class MediaAsset : AggregateRoot
{
    public MediaAsset(MediaKind kind, string storageKey, string mime, long sizeBytes, int? width, int? height,
        string? altAr, string? altEn, string? createdBy, DateTimeOffset now) : base(Guid.CreateVersion7())
    {
        Guard.Against(kind == MediaKind.Image && string.IsNullOrWhiteSpace(altAr), "media.alt_required");
        Guard.Against(sizeBytes <= 0, "media.size_invalid");
        Kind = kind;
        StorageKey = Guard.NotEmpty(storageKey);
        IsPublic = true;
        Mime = Guard.NotEmpty(mime);
        SizeBytes = sizeBytes;
        Width = width;
        Height = height;
        AltAr = altAr?.Trim();
        AltEn = string.IsNullOrWhiteSpace(altEn) ? null : altEn.Trim();
        CreatedBy = createdBy;
        CreatedAt = now;
    }

    private MediaAsset()
    {
    }

    public MediaKind Kind { get; private set; }

    public string StorageKey { get; private set; } = null!;

    public bool IsPublic { get; private set; }

    public string Mime { get; private set; } = null!;

    public long SizeBytes { get; private set; }

    public int? Width { get; private set; }

    public int? Height { get; private set; }

    public string? AltAr { get; private set; }

    public string? AltEn { get; private set; }

    public DateTimeOffset CreatedAt { get; private set; }

    public string? CreatedBy { get; private set; }

    /// A public image: the only kind a project cover or a category image may point at (D-06).
    public bool IsPublicImage => Kind == MediaKind.Image && IsPublic;

    public void SetAlt(string? altAr, string? altEn)
    {
        Guard.Against(Kind == MediaKind.Image && string.IsNullOrWhiteSpace(altAr), "media.alt_required");
        AltAr = altAr?.Trim();
        AltEn = string.IsNullOrWhiteSpace(altEn) ? null : altEn.Trim();
        Raise(new CatalogChanged("media", Id, "alt"));                   // L-14: alt texts are on the static site
    }
}
